insert into wx_fans_bind ( patient_id, dictionary_id,open_id,union_id,bind,bind_time,is_vip,is_owner, crt_id)
VALUES

    (#{item.patientId}, #{item.dictionaryId}, #{item.openId}, #{item.unionId},
    #{item.bind}, #{item.bindTime},#{item.isVip},
    #{item.isOwner}, #{item.crtId}
    )

mapper.select:
select wf.open_id as openId, wfb.patient_id as patientId, wf.nick_name as nickName from wx_fans_bind wfb inner join wx_fans wf on wf.open_id = wfb.open_id where wfb.patient_id in
#{item}
and wfb.`bind` = 1

SELECT wfb.patient_id as patientId, wfb.union_id as unionId, wfb.dictionary_id as dictionaryId, wfb.crt_time as crtTime, pbi.name as name, pbi.mobile as mobile, pbi.gender as gender FROM wx_fans_bind wfb LEFT JOIN patient_base_info pbi ON wfb.patient_id = pbi.id
AND wfb.union_id = #{unionId}
order by wfb.crt_time desc
